import{_ as t,o as e,c as a,Q as r}from"./chunks/framework.b67c47e6.js";const b=JSON.parse('{"title":"Logistics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logistics/index.md","filePath":"guide/logistics/index.md","lastUpdated":1786804877000}'),o={name:"guide/logistics/index.md"},i=r('<h1 id="logistics" tabindex="-1">Logistics <a class="header-anchor" href="#logistics" aria-label="Permalink to &quot;Logistics&quot;">​</a></h1><p>The Logistics view provides an overview of material requirements across your constructibles, helping you track which parts are available and which still need to be prepared.</p><nav class="table-of-contents"><ul><li><a href="#layout">Layout</a></li><li><a href="#material-tracking">Material Tracking</a></li><li><a href="#sorting">Sorting</a></li><li><a href="#filtering">Filtering</a></li><li><a href="#part-batches">Part Batches</a><ul><li><a href="#material-returned-to-stock">Material returned to stock</a></li><li><a href="#where-the-batches-live">Where the batches live</a></li></ul></li><li><a href="#marking-parts-ready">Marking Parts Ready</a></li><li><a href="#part-drawings">Part Drawings</a></li><li><a href="#connection-to-other-features">Connection to Other Features</a></li></ul></nav><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The logistics interface has three panels:</p><ul><li><strong>Left panel</strong> — Branch selection (plates or profiles) and size filters.</li><li><strong>Center panel</strong> — Material inventory table grouped by zone.</li><li><strong>Right panel</strong> — Detailed information for the selected item.</li></ul><h2 id="material-tracking" tabindex="-1">Material Tracking <a class="header-anchor" href="#material-tracking" aria-label="Permalink to &quot;Material Tracking&quot;">​</a></h2><p>The table shows each material part needed for production, organized by:</p><table><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Zone</strong></td><td>The structural area in the design where this part is used. Projects without zones don&#39;t show this column.</td></tr><tr><td><strong>Reference</strong></td><td>Material identification code.</td></tr><tr><td><strong>Material</strong></td><td>Material name.</td></tr><tr><td><strong>Dimensions</strong></td><td>Width and length (for plates) or length (for profiles).</td></tr><tr><td><strong>Total</strong></td><td>Total number of this part needed across all constructibles.</td></tr><tr><td><strong>Pending</strong></td><td>How many are still to be prepared.</td></tr><tr><td><strong>% ready</strong></td><td>Progress of the row.</td></tr><tr><td><strong>Constructibles</strong></td><td>Breakdown showing how many are needed for each assembly/module. Long lists are cut to three, with the rest behind a <code>+N</code> chip.</td></tr><tr><td><strong>Ready parts</strong></td><td>How many have been prepared and are available.</td></tr></tbody></table><p>A totals line at the bottom sums up rows, parts, ready, pending and the overall percentage.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Click any column header to sort by it, and shift-click a second header to sort by both. Zone and reference sort naturally, so <code>Z2</code> comes before <code>Z10</code> and reference <code>9</code> before <code>114</code>.</p><p>The <strong>Sort</strong> menu has four ready-made orders:</p><ul><li><strong>Longest first</strong> — the default, for cutting at the saw.</li><li><strong>Reference A-Z</strong> — to find a specific part.</li><li><strong>Pending first</strong> — to see what is still missing.</li><li><strong>Zone then reference</strong> — the kitting order.</li></ul><p>The same menu switches between <strong>Group by zone</strong>, where each zone is a header row with its own progress and the sorting applies inside it, and <strong>Flat list</strong>, where the order applies to the whole table. Projects without zones always use the flat list.</p><p>Your sorting, grouping, density and hidden columns are remembered on the device.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><ul><li><strong>Branch</strong> — Switch between viewing plate materials or profile materials.</li><li><strong>Size</strong> — Filter to a specific material size. One at a time: this is a production view, and a run at the saw is one size.</li><li><strong>Search</strong> — Filter the table by reference, zone or material.</li><li><strong>Hide completed</strong> — Leave only the rows with parts still pending.</li></ul><h2 id="part-batches" tabindex="-1">Part Batches <a class="header-anchor" href="#part-batches" aria-label="Permalink to &quot;Part Batches&quot;">​</a></h2><p>A part batch is a run of work: the parts you are about to cut, from the moment you start until you finish and put the leftover material back.</p><p>A <strong>batch bar</strong> sits above the table:</p><ol><li><strong>Pick a batch</strong> in the selector, if somebody prepared one for you in the parts list. Picking it makes the table show that batch and nothing else.</li><li><strong>Start production</strong> — with no batch picked, this creates one out of what is on the table (your selection, the branch and the size) and starts it. <strong>Start batch</strong> does the same for the batch you picked. Either way, who started it and when are recorded, and from then on the counters work. Before that, the counters are locked and <em>Set all parts ready</em> is not there.</li><li><strong>While it runs</strong>, the bar shows the progress of the whole batch and the time worked. <strong>Pause</strong> stops the clock; the counters lock again until you resume.</li><li><strong>Finish batch</strong> — or marking the last pending part — opens the form for the material that goes back to stock.</li></ol><p>Several batches can run at the same time, and you can switch between them whenever you want. If you leave a running batch — by picking another one, by changing the selection, or by navigating away — you are asked whether to pause the one you are leaving, exactly like leaving a panel with an open checklist in the viewer.</p><p>Nothing happens automatically overnight: a batch stays open until somebody pauses or finishes it.</p><h3 id="material-returned-to-stock" tabindex="-1">Material returned to stock <a class="header-anchor" href="#material-returned-to-stock" aria-label="Permalink to &quot;Material returned to stock&quot;">​</a></h3><p>The closing form asks only for what <strong>comes back</strong>, in the units you buy it in:</p><ul><li><strong>Returned whole</strong> — bars or sheets that go back unopened.</li><li><strong>Remnants</strong> — the usable offcuts, with their length (and width, for sheets).</li><li><strong>Scrap</strong> — what is thrown away.</li><li><strong>Rack</strong> — where you leave it, and a free notes field.</li></ul><p>If the bar length or sheet size you used is not in the list, type it and it is added to your product catalogue, so next time it is already there.</p><p>Closing with <strong>Nothing to return</strong> is a normal outcome and needs no explanation.</p><p>Produuz.it does not keep stock levels: this declaration is sent onwards, to the system that does.</p><h3 id="where-the-batches-live" tabindex="-1">Where the batches live <a class="header-anchor" href="#where-the-batches-live" aria-label="Permalink to &quot;Where the batches live&quot;">​</a></h3><p><strong>Part batches</strong> in the company menu lists them all: status, production line, project, progress, start, finish, time worked and who ran them. Clicking the name opens a panel on the right with the batch in full — its parts, its work sessions and the material declared as returned — and the buttons to open it in the logistics view, pause or resume it, finish it and reopen it.</p><p>The <strong>production line</strong> is changed from that panel. It is the only field of a batch you can edit there, and it is saved as soon as you pick it.</p><p>Batches can also be composed by hand from the <strong>Parts list</strong>, by selecting parts and assigning them to a batch. That is the place to build a batch that mixes several sizes: the logistics view always works on one size at a time.</p><h2 id="marking-parts-ready" tabindex="-1">Marking Parts Ready <a class="header-anchor" href="#marking-parts-ready" aria-label="Permalink to &quot;Marking Parts Ready&quot;">​</a></h2><p>You can update the &quot;ready parts&quot; count for each material to track preparation progress:</p><ul><li>Click on the number to type it, or use the <code>−</code> and <code>+</code> buttons.</li><li>Use the <strong>Set all parts ready</strong> button to mark everything currently listed as ready. It asks for confirmation first. Without a batch it only affects the rows you can see — so searching or hiding completed rows narrows it down — while with a batch running it marks the whole batch, and says so.</li></ul><h2 id="part-drawings" tabindex="-1">Part Drawings <a class="header-anchor" href="#part-drawings" aria-label="Permalink to &quot;Part Drawings&quot;">​</a></h2><p>When a part is selected, the right panel shows its drawings — combined, front, top, left and section views — for quick reference on the workshop floor.</p><p>Only views that show real features (cutouts, holes, bevels, non-rectangular profiles) are produced. If a particular view would just be a plain rectangle, it&#39;s skipped — the dimensions in the table already convey that. A part with no features at all gets no drawings.</p><p>For wood parts that aren&#39;t straight prisms (parts with cutouts, bevels or mitres), an extra <strong>3D</strong> button appears next to the drawing views. Clicking it opens the isolated part in an interactive 3D viewer, so any feature that&#39;s hard to read on a 2D drawing can be inspected directly. The button only shows up when this 3D model is available.</p><h2 id="connection-to-other-features" tabindex="-1">Connection to Other Features <a class="header-anchor" href="#connection-to-other-features" aria-label="Permalink to &quot;Connection to Other Features&quot;">​</a></h2><ul><li>Material requirements are derived from the designs and their BoM data.</li><li>The <a href="/guide/logistics/delivery/">Delivery &amp; Racks</a> feature uses the logistics data to plan how completed assemblies are loaded for transport.</li><li><a href="/guide/reports/">Reports</a> can generate Bills of Materials for ordering the materials tracked here.</li></ul>',43),n=[i];function s(l,h,d,c,g,u){return e(),a("div",null,n)}const f=t(o,[["render",s]]);export{b as __pageData,f as default};
